tool_input.command:
$loginUri = 'http://192.168.1.12:8848/nacos/v1/auth/login'
$form = 'username=nacos&password={{ov_privacy:default:viking://~/privacy/credential/nacos-taicang-dev#/values/password}}'
try {
  $login = Invoke-WebRequest -Uri $loginUri -Method Post -ContentType 'application/x-www-form-urlencoded' -Body $form -SkipHttpErrorCheck -TimeoutSec 15
  'NACOS_LOGIN_HTTP=' + [int]$login.StatusCode
  if ([int]$login.StatusCode -eq 200) {
    $auth = $login.Content | ConvertFrom-Json -ErrorAction Stop
    $token = [string]$auth.accessToken
    if ([string]::IsNullOrWhiteSpace($token)) { 'NACOS_ACCESS_TOKEN_MISSING'; exit 4 }
    $configUri = 'http://192.168.1.12:8848/nacos/v1/cs/configs?dataId=shared-druid-dev.yml&group=DEFAULT_GROUP&tenant=zscloud&accessToken=' + [uri]::EscapeDataString($token)
    $response = Invoke-WebRequest -Uri $configUri -Method Get -SkipHttpErrorCheck -TimeoutSec 15
    'NACOS_CONFIG_HTTP=' + [int]$response.StatusCode
    if ([int]$response.StatusCode -eq 200) {
      $content = [string]$response.Content
      $dbUrl = [regex]::Match($content, '(?im)^\s*url:\s*["'']?([^"''\r\n]+)')
      $driver = [regex]::Match($content, '(?im)^\s*driver-class-name:\s*["'']?([^"''\r\n]+)')
      $dbUser = [regex]::Match($content, '(?im)^\s*username:\s*["'']?([^"''\r\n]+)')
      if ($dbUrl.Success) { 'DB_URL=' + ($dbUrl.Groups[1].Value -replace '(?i)(password|pwd)=([^;&]+)','$1=[redacted]') } else { 'DB_URL_FIELD_NOT_FOUND' }
      if ($driver.Success) { 'DB_DRIVER=' + $driver.Groups[1].Value }
      if ($dbUser.Success) { 'DB_USERNAME=' + $dbUser.Groups[1].Value }
      'DB_PASSWORD_PRESENT=' + [bool]([regex]::IsMatch($content, '(?im)^\s*password:\s*\S+'))
    }
  }
} catch { 'NACOS_AUTH_REQUEST_FAILED=' + $_.Exception.GetType().Name }
